function createPendingLogins() {
  const logins = new Map();
  return {
    save(loginId, state) {
      logins.set(loginId, state);
    },
    take(loginId, state) {
      const expected = logins.get(loginId);
      logins.delete(loginId);
      return typeof expected === "string" && typeof state === "string" && expected === state;
    },
  };
}

const pending = createPendingLogins();
pending.save("L1", "state-abc");
pending.save("L2", "state-xyz");
console.log(pending.take("L1", "attacker-state"));
console.log(pending.take("L1", "state-abc"));
console.log(pending.take("L2", "state-xyz"));
console.log(pending.take("L2", "state-xyz"));
console.log(pending.take(undefined, undefined));

