const expected = { issuer: "https://id.bank.example", clientId: "budget-app", nonce: "n-42", now: 1790244000 };
const good = { iss: "https://id.bank.example", aud: "budget-app", sub: "248289761001", exp: 1790244600, nonce: "n-42" };

function checkIdToken(claims, { issuer, clientId, nonce, now }) {
  if (claims.iss !== issuer) return "issuer";
  if (claims.aud !== clientId) return "audience";
  if (typeof claims.exp !== "number" || claims.exp <= now) return "expired";
  if (claims.nonce !== nonce) return "nonce";
  return "ok";
}

console.log([
  checkIdToken(good, expected),
  checkIdToken({ ...good, iss: "https://id.evil.example" }, expected),
  checkIdToken({ ...good, aud: "quiz-app" }, expected),
  checkIdToken({ ...good, exp: 1790243000 }, expected),
  checkIdToken({ ...good, nonce: "n-41" }, expected),
].join(" "));

