const now = 1000;
const tokens = new Map([
  ["tok-read", { scopes: ["transactions:read"], expiresAt: 2000 }],
  ["tok-old", { scopes: ["transactions:read", "transactions:write"], expiresAt: 900 }],
]);

function guard(tokens, authorization, requiredScope) {
  const value = typeof authorization === "string" && authorization.startsWith("Bearer ") ? authorization.slice(7) : "";
  const info = tokens.get(value);
  if (!info || info.expiresAt <= now) return { status: 401, error: "invalid_token" };
  if (!info.scopes.includes(requiredScope)) return { status: 403, error: "insufficient_scope" };
  return { status: 200 };
}

