const clients = {
  "budget-app": { redirectUris: ["https://budget.example/callback"], scopes: ["openid", "email", "transactions:read"] },
};

function checkAuthorize(params, clients) {
  const client = clients[params.get("client_id")];
  if (!client || !client.redirectUris.includes(params.get("redirect_uri"))) return "error page";
  if (params.get("code_challenge_method") !== "S256") return "redirect error=invalid_request";
  const scopes = (params.get("scope") ?? "").split(" ");
  if (!scopes.every((s) => client.scopes.includes(s))) return "redirect error=invalid_scope";
  return "redirect code";
}

const good = "client_id=budget-app&redirect_uri=https://budget.example/callback&scope=openid email&code_challenge_method=S256";
const variants = [
  good,
  good.replace("budget.example/callback", "evil.example/callback"),
  good.replace("S256", "plain"),
  good.replace("openid email", "openid transactions:write"),
  good.replace("budget-app", "unknown-app"),
];
for (const query of variants) console.log(checkAuthorize(new URLSearchParams(query), clients));

