function buildAuthorizeUrl(base, { clientId, redirectUri, scopes, state, nonce, challenge }) {
  const url = new URL("/authorize", base);
  url.search = new URLSearchParams({
    response_type: "code",
    client_id: clientId,
    redirect_uri: redirectUri,
    scope: scopes.join(" "),
    state,
    nonce,
    code_challenge: challenge,
    code_challenge_method: "S256",
  });
  return url.href;
}

const url = buildAuthorizeUrl("https://id.bank.example", {
  clientId: "budget-app",
  redirectUri: "https://budget.example/callback",
